INSERT INTO feature VALUES('exact-distributions','theory','Finite distributions with exact weights',NULL,'partial','notable',NULL,'A distribution puts an exact positive weight, a 128-bit rational, on each point of a finite support in one canonical order, so equality in distribution is the equality of forms. The finite Giry monad (`point`, `uniform`, `map`, `bind`), the product with its two marginals, the restriction to an event, and the decision of independence, which names the first pair where a joint and the product of its marginals differ, hold the three monad laws and Bayes'' rule by enumeration. A weight past the integers and an event of weight zero are refused by name. `@[ distributes(…) ]` states the exact distribution of a declaration''s runs: the corpus runs it once for each sequence of answers to its `std.rand.Eff` draws, depth first, gives each path the weight `2^-n` of its `n` bits, and compares the sum by outcome with the stated weights; a path past 16 bits is refused by name. A forked task and a `migrate` body draw as the root does, and the host of the run answers each draw. A draw that the exact model declines is refused by name, with the task or the world that performs it. std states three exact distributions: the first output of `std.rand.lcg` over a uniform seed is uniform, two keys collide under the multiply-shift family of `std.hash` at most at its bound `2 / 2^m`, met at the worst pair, and the ciphertext of the one-time pad of `std.crypto` is decided independent of its message. Probability sheaves over an atomic site and conditioning across the worlds of a run are the next rung.','theory-probability core-checker runtime-emitter surface-corpus surface-dispatcher surface-lowering','corpus/ledger/features/exact-distributions.gandr crates/theory-probability/tests/monad.rs crates/theory-probability/tests/canonical.rs crates/theory-probability/tests/joint.rs crates/theory-probability/tests/condition.rs corpus/model/probability/draws.gandr corpus/model/probability/coin-exchange.gandr corpus/model/probability/leader.gandr corpus/ledger/attributes/distributes.gandr corpus/model/probability/seeded.gandr corpus/model/probability/hashing.gandr corpus/model/probability/one-time-pad.gandr crates/surface-dispatcher/tests/corpus.rs','corpus/ledger/features/exact-distributions.gandr','#6120');
